sys_script_include.script:
var LendingApplicationLookup = Class.create();
LendingApplicationLookup.prototype = {
    initialize: function() {},

    cleanPhone: function(phone) {
        if (!phone) return "";
        return ("" + phone).replace(/\D/g, "");
    },

    lookupApplication: function(inputs, outputs) {
        inputs = inputs || {};
        var appNumber = inputs.application_number || inputs.case_number || "";
        var contactId = inputs.contact_sys_id || "";
        var accountId = inputs.account_sys_id || "";
        var phone = inputs.phone_number || "";

        var result = {
            success: false,
            application_found: false,
            application_number: "",
            application_sys_id: "",
            case_number: "",
            case_sys_id: "",
            table: "sn_bom_loan_b2b_service",
            loan_description: "",
            service_definition: "",
            current_stage: "",
            current_state: "",
            priority: "",
            customer_account: "",
            account_sys_id: "",
            customer_contact: "",
            contact_sys_id: "",
            has_pending_tasks: false,
            pending_tasks_count: 0,
            pending_tasks_summary: "",
            tasks: [],
            portal_upload_url: "https://luminabankpab.service-now.com/csm?id=csm_tasks",
            submission_email: "lending-documents@luminabank.com",
            voice_agent_message: ""
        };

        // 1. Resolve Contact / Account if phone provided
        if (phone && !contactId && !accountId) {
            var digits = this.cleanPhone(phone);
            var last10 = digits.length >= 10 ? digits.slice(-10) : digits;
            var contactGR = new GlideRecord("customer_contact");
            var qc = contactGR.addQuery("phone", "CONTAINS", last10);
            qc.addOrCondition("mobile_phone", "CONTAINS", last10);
            qc.addOrCondition("home_phone", "CONTAINS", last10);
            contactGR.setLimit(1);
            contactGR.query();
            if (contactGR.next()) {
                contactId = contactGR.getUniqueValue();
                result.contact_sys_id = contactId;
                result.customer_contact = contactGR.getDisplayValue("name");
                if (contactGR.account) {
                    accountId = contactGR.account.toString();
                    result.account_sys_id = accountId;
                    result.customer_account = contactGR.account.getDisplayValue();
                }
            }
        }

        // 2. Query active loan case on sn_bom_loan_b2b_service
        var caseGR = new GlideRecord("sn_bom_loan_b2b_service");
        if (appNumber) {
            var q = caseGR.addQuery("number", appNumber);
            q.addOrCondition("x_snc_pab_ee_tkit_application_number", appNumber);
        } else if (contactId) {
            caseGR.addQuery("contact", contactId);
            caseGR.addQuery("active", true);
        } else if (accountId) {
            caseGR.addQuery("account", accountId);
            caseGR.addQuery("active", true);
        } else {
            caseGR.addQuery("active", true);
        }
        caseGR.orderByDesc("sys_created_on");
        caseGR.setLimit(1);
        caseGR.query();

        if (caseGR.next()) {
            result.success = true;
            result.application_found = true;
            result.application_number = caseGR.getValue("x_snc_pab_ee_tkit_application_number") || caseGR.getValue("number");
            result.case_number = caseGR.getValue("number");
            result.application_sys_id = caseGR.getUniqueValue();
            result.case_sys_id = caseGR.getUniqueValue();
            result.loan_description = caseGR.getValue("short_description") || "Business Equipment Loan Application";
            result.service_definition = caseGR.service_definition ? caseGR.service_definition.getDisplayValue() : "Business Equipment Loan Application";
            result.current_stage = caseGR.getDisplayValue("stage") || caseGR.getValue("stage") || "Credit Assessment";
            result.current_state = caseGR.getDisplayValue("state") || "Awaiting Info";
            result.priority = caseGR.getDisplayValue("priority") || "2 - High";
            result.customer_account = caseGR.account ? caseGR.account.getDisplayValue() : result.customer_account;
            result.account_sys_id = caseGR.account ? caseGR.account.toString() : result.account_sys_id;
            result.customer_contact = caseGR.contact ? caseGR.contact.getDisplayValue() : result.customer_contact;
            result.contact_sys_id = caseGR.contact ? caseGR.contact.toString() : result.contact_sys_id;

            // 3. Query open customer-facing tasks on sn_bom_loan_b2b_task
            var taskGR = new GlideRecord("task");
            taskGR.addQuery("parent", caseGR.getUniqueValue());
            taskGR.addQuery("active", true);
            var qvis = taskGR.addQuery("visible_to_customer", true);
            if (result.contact_sys_id) {
                qvis.addOrCondition("assigned_to", result.contact_sys_id);
                qvis.addOrCondition("watch_list", "CONTAINS", result.contact_sys_id);
            }
            taskGR.orderBy("number");
            taskGR.query();

            var taskSummaries = [];
            while (taskGR.next()) {
                var taskObj = {
                    task_number: taskGR.getValue("number"),
                    sys_id: taskGR.getUniqueValue(),
                    short_description: taskGR.getValue("short_description"),
                    service_definition: taskGR.service_definition ? taskGR.service_definition.getDisplayValue() : "",
                    state: taskGR.getDisplayValue("state"),
                    assigned_to: taskGR.assigned_to ? taskGR.assigned_to.getDisplayValue() : "",
                    due_date: taskGR.getValue("due_date") || ""
                };
                result.tasks.push(taskObj);

                var cleanDesc = taskObj.short_description.replace(/^Awaiting Documents\s*-\s*/i, "");
                taskSummaries.push(cleanDesc);
            }

            result.pending_tasks_count = result.tasks.length;
            result.has_pending_tasks = result.tasks.length > 0;
            result.pending_tasks_summary = taskSummaries.join(", ");

            // 4. Construct natural, conversational voice prompt for Voice AI Agent
            var voiceMsg = "I have located your active " + result.loan_description + ", application number " + result.application_number + ". ";
            voiceMsg += "Your application is currently in the " + result.current_stage + " stage. ";

            if (result.has_pending_tasks) {
                if (result.pending_tasks_count === 1) {
                    voiceMsg += "To proceed with the assessment, there is one pending document required from you: " + result.pending_tasks_summary + ". ";
                } else {
                    voiceMsg += "To proceed with the assessment, there are " + result.pending_tasks_count + " pending documents required from you: " + taskSummaries.join(" and ") + ". ";
                }
                voiceMsg += "These tasks require your attention. You can submit these documents either by uploading them directly through the customer portal, or by emailing them to " + result.submission_email + ".";
            } else {
                voiceMsg += "There are currently no outstanding tasks requiring your attention at this time.";
            }

            result.voice_agent_message = voiceMsg;
        } else {
            result.voice_agent_message = "I was unable to locate an active lending application matching your details. Please verify your application number or contact an account specialist for assistance.";
        }

        this._populateOutputs(result, outputs);
        return result;
    },

    _populateOutputs: function(result, outputs) {
        if (!outputs) return;
        outputs.application_found = result.application_found;
        outputs.application_number = result.application_number || "";
        outputs.case_number = result.case_number || result.application_number || "";
        outputs.application_sys_id = result.application_sys_id || "";
        outputs.case_sys_id = result.case_sys_id || result.application_sys_id || "";
        outputs.contact_sys_id = result.contact_sys_id || "";
        outputs.account_sys_id = result.account_sys_id || "";
        outputs.loan_description = result.loan_description || "";
        outputs.current_stage = result.current_stage || "";
        outputs.current_state = result.current_state || "";
        outputs.has_pending_tasks = result.has_pending_tasks;
        outputs.pending_tasks_count = result.pending_tasks_count || 0;
        outputs.pending_tasks_summary = result.pending_tasks_summary || "";
        outputs.voice_agent_message = result.voice_agent_message || "";
        outputs.submission_email = result.submission_email || "";
        outputs.portal_upload_url = result.portal_upload_url || "";
        outputs.tasks_json = JSON.stringify(result.tasks || []);
        outputs.result_json = JSON.stringify(result);
    },

    type: "LendingApplicationLookup"
};
